package com.coworkhub.service;
import com.coworkhub.entity.*;import com.coworkhub.repository.BookingRepository;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.BeforeEach;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.math.*;import java.time.*;import java.util.*;
class BookingPricingServiceImplTest {
 private BookingRepository repository;private BookingPricingServiceImpl pricing;
 @BeforeEach void setup(){repository=mock(BookingRepository.class);pricing=new BookingPricingServiceImpl(repository);when(repository.findByMemberIdAndStartTimeBetween(anyLong(),any(LocalDateTime.class),any(LocalDateTime.class))).thenReturn(List.of());}
 @Test void includedHoursAreFreeAndOnlyExcessIsCharged(){Member member=new Member();member.id=1L;member.plan=new MembershipPlan();member.plan.includedHoursPerMonth=10;member.plan.overageDiscount=20;Room room=new Room();room.hourlyRate=new BigDecimal("1000.00");LocalDateTime start=LocalDateTime.of(2030,5,10,10,0);BigDecimal cost=pricing.calculateRoomCost(member,room,start,start.plusHours(12));assertEquals(new BigDecimal("1600.00"),cost);}
 @Test void cancelledBookingsDoNotConsumeIncludedHours(){Member member=new Member();member.id=2L;member.plan=new MembershipPlan();member.plan.includedHoursPerMonth=5;member.plan.overageDiscount=0;Room room=new Room();room.hourlyRate=new BigDecimal("100.00");Booking cancelled=new Booking();cancelled.startTime=LocalDateTime.of(2030,6,1,8,0);cancelled.endTime=cancelled.startTime.plusHours(5);cancelled.status=Enums.BookingStatus.CANCELLED;when(repository.findByMemberIdAndStartTimeBetween(anyLong(),any(LocalDateTime.class),any(LocalDateTime.class))).thenReturn(List.of(cancelled));LocalDateTime start=LocalDateTime.of(2030,6,10,9,0);assertEquals(BigDecimal.ZERO,pricing.calculateRoomCost(member,room,start,start.plusHours(1)));}
}
